  if (typeof expr === 'number') return expr;
  if (typeof expr === 'string') return env[expr];
  if (expr[0] === '+') return myEval(expr[1], env) + myEval(expr[2], env);
  if (expr[0] === '>') return myEval(expr[1], env) > myEval(expr[2], env);
  if (expr[0] === 'if') {
    return myEval(expr[1], env) ? myEval(expr[2], env) : myEval(expr[3], env);
  }
  throw new Error('unsupported expression');
}

